185	\section{Distance measures}
186	
187	\begin{definition}[Distance between states]\label{def:state-distance}
188		Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
189		\[
190			\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
191		\]
192		The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
193	\end{definition}
194	
195	\begin{definition}[Consistency between POVMs]\label{def:consistency}
196		\lean{MIPStarRE.QPBT.consistencyDefect, MIPStarRE.QPBT.IsConsistentWithin}
197		\leanok
198		\uses{def:povm-conventions, def:state-distance}
199		Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H_A \ot \mathcal H_B$ be a quantum state, and for all $x \in \mathcal X$ let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. We write
200		\[
201			A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a
202		\]
203		on state $\ket{\psi}$ and distribution $\mu$ if
204		\[
205			\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
206		\]
207		In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
208	\end{definition}
209	
210	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
